"""Build the audience guides from one source for both brands and the RK preview.

Run with Python; optionally pass the Outlaw Apps repository to export its preview.
Screenshots are captured from the real application, never invented statistics.
"""
from pathlib import Path
from html import escape
import shutil
import sys

ROOT = Path(__file__).resolve().parents[1]
CSS = '''
*{box-sizing:border-box}html{scroll-behavior:smooth;scroll-padding-top:24px}body{margin:0;background:var(--bg);color:var(--ink);font:16px/1.7 Inter,system-ui,sans-serif}a{color:inherit}a:hover{color:var(--accent)}a:focus-visible,summary:focus-visible,button:focus-visible{outline:3px solid var(--accent);outline-offset:5px}header{border-bottom:1px solid var(--line)}.top{max-width:1180px;margin:auto;padding:20px 28px;display:flex;align-items:center;justify-content:space-between;gap:24px}.brand{display:flex;align-items:center;text-decoration:none}.brand img{max-width:240px;max-height:64px;object-fit:contain}.brand span{font-size:20px;font-weight:800}.top nav{display:flex;flex-wrap:wrap;gap:20px;font-size:14px;font-weight:650}.top nav a{text-decoration:none}.top nav a[aria-current]{color:var(--accent)}main{max-width:1180px;padding:0 28px 80px;margin:auto}.hero{padding:76px 0 56px;max-width:960px}.eyebrow{color:var(--accent);text-transform:uppercase;font-size:12px;letter-spacing:.18em;font-weight:800}h1{font-size:clamp(42px,6.2vw,76px);line-height:1.06;letter-spacing:-.055em;margin:18px 0 24px;max-width:850px}h2{font-size:clamp(28px,3.3vw,40px);line-height:1.15;letter-spacing:-.035em;margin:12px 0 18px}h3{font-size:21px;line-height:1.3;margin:0 0 10px}p{margin:0 0 18px}.lede{font-size:21px;line-height:1.6;color:var(--muted);max-width:760px}.buttons{display:flex;gap:12px;flex-wrap:wrap;margin-top:28px}.button{background:var(--accent);color:#170f0a!important;text-decoration:none;padding:12px 19px;border-radius:8px;font-weight:750}.button.secondary{background:var(--card);color:var(--ink)!important;border:1px solid var(--line)}.jump{display:flex;flex-wrap:wrap;gap:10px;padding-bottom:30px;border-bottom:1px solid var(--line)}.jump a{background:var(--card);border:1px solid var(--line);border-radius:30px;padding:6px 14px;text-decoration:none;font-size:13px}section{padding:56px 0;border-bottom:1px solid var(--line)}.split{display:grid;grid-template-columns:1fr 1fr;gap:38px;align-items:start}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;margin-top:28px}.card{padding:24px;background:var(--card);border:1px solid var(--line);border-radius:12px}.card p{font-size:15px;color:var(--muted);margin:0}.note{padding:20px 24px;border-left:3px solid var(--accent);background:var(--card);border-radius:0 10px 10px 0;margin:24px 0;color:var(--muted)}strong{color:var(--ink)}figure{margin:26px 0 0}figure a{display:block;border:1px solid var(--line);border-radius:12px;overflow:hidden;background:var(--card)}figure img{display:block;width:100%;height:auto}figcaption{font-size:12px;color:var(--muted);margin:10px 2px;line-height:1.6}details{margin:20px 0;background:var(--card);border:1px solid var(--line);border-radius:12px;overflow:hidden}summary{cursor:pointer;padding:20px 24px;font-weight:750;list-style:none;display:flex;gap:20px;align-items:center;justify-content:space-between}summary::-webkit-details-marker{display:none}summary::after{content:'+';font-size:26px;color:var(--accent);line-height:1}details[open] summary::after{content:'−'}details[open] summary{border-bottom:1px solid var(--line)}.inside{padding:10px 24px 24px}ol{padding-left:24px}li{padding-left:6px;margin:16px 0}li p{color:var(--muted);margin:4px 0}code{font-size:.9em;background:var(--bg);padding:2px 5px;border-radius:4px}.closing{padding:48px 0 0}footer{border-top:1px solid var(--line);padding:24px 28px;font-size:13px;color:var(--muted)}.footer-in{max-width:1124px;margin:auto;display:flex;justify-content:space-between;flex-wrap:wrap;gap:16px}.preview{padding:9px 20px;text-align:center;background:#fff8ed;color:#171717;font-size:12px}.preview a{color:#9d3514}.shot-grid{display:grid;grid-template-columns:1fr 1fr;gap:24px}.muted{color:var(--muted)}@media(max-width:760px){.top{align-items:flex-start;flex-direction:column;padding:18px 20px;gap:14px}.brand img{max-width:215px}.top nav{gap:16px}main{padding:0 20px 48px}.hero{padding:44px 0 32px}.lede{font-size:18px}.split,.cards,.shot-grid{grid-template-columns:1fr;gap:22px}section{padding:36px 0}.inside,summary{padding-left:18px;padding-right:18px}footer{padding:24px 20px}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}}
'''

def image(name, caption, assets):
    path = assets + '/' + name + '.png'
    return f'<figure><a href="{path}" target="_blank" rel="noopener" aria-label="Open full-size screenshot: {escape(caption)}"><img src="{path}" alt="{escape(caption)}" loading="lazy" decoding="async"></a><figcaption>{caption} · Actual application screenshot. Select the image to enlarge.</figcaption></figure>'

def artists(link, assets):
    return f'''
<div class="hero"><p class="eyebrow">For artists</p><h1>Your discography.<br>Your words. Your audience.</h1><p class="lede">Give listeners one place to explore your releases, follow the lyrics, build playlists, and keep your music playing wherever they go. Upload your own recordings, share your artist page, and see how people listen.</p><div class="buttons"><a class="button" href="{link('/artist-upload')}">Publish your music</a><a class="button secondary" href="#stats">See the artist dashboard</a></div></div>
<nav class="jump" aria-label="On this page"><a href="#upload">Upload a release</a><a href="#lyrics">Lyrics &amp; syncing</a><a href="#playback">Background &amp; CarPlay</a><a href="#stats">Listening stats</a><a href="#share">Reach your listeners</a></nav>
<section id="upload"><p class="eyebrow">01 / Publish</p><h2>From your files to a full artist page.</h2><p class="lede">Albums, singles, artwork, track names, and release dates stay together. Fans get a discography they can explore, rather than a folder of disconnected files.</p><details><summary>How to upload and publish your music</summary><div class="inside"><ol><li><strong>Sign in and open Publish My Music.</strong><p>Start with the artist upload page. Choose the artist you manage, or create a private artist draft for your first release.</p></li><li><strong>Create a release.</strong><p>In the discography uploader, enter the release title and original release date, or mark it unreleased. Add your cover artwork, then choose your audio files. MP3, M4A, WAV, FLAC, OGG, and Opus files are accepted; the uploader shows your current file and storage allowances.</p></li><li><strong>Check the track list and upload.</strong><p>Review each song title and track number before starting. Upload one release at a time. If a file fails, retry that file without starting the whole release over.</p></li><li><strong>Complete the rights and licensing step.</strong><p>Use the artist publishing flow to provide the rights information and sign the catalog license. You must control the recordings and the music and lyrics needed to distribute them. Draft uploads stay private while the submission is reviewed.</p></li><li><strong>After approval, share your artist page.</strong><p>The approved audio becomes available to your audience. Add lyrics and timing, check the public release, then share the artist or album link with your fans.</p></li></ol><p><a href="{link('/artist-discography-upload')}">Open the release uploader →</a> &nbsp; <a href="{link('/artist-agreement')}">Read the artist agreement →</a></p></div></details>{image('artist-upload','The real release uploader: artist selection, release details, artwork, and audio files.',assets)}<div class="note"><strong>Public artist publishing and personal audio uploads are separate.</strong> Publish original music you control through the artist rights process. Uploading an audio file to a personal account does not distribute it to everyone.</div></section>
<section id="lyrics"><p class="eyebrow">02 / Add the words</p><h2>Lyrics that belong beside the record.</h2><div class="split"><div><h3>Upload a whole album’s lyrics</h3><p>Open <strong>Manage My Artists</strong>, find the album, and select <strong>Lyrics</strong>. Paste the complete album or choose a <code>.txt</code>, <code>.md</code>, or <code>.lrc</code> file.</p><p>Put each song title on its own line—<code>1. Title</code>, <code>[Title]</code>, <code>## Title</code>, or the title itself. Choose <strong>Split by song</strong>, check the song assignments and words, then save. You can also use <strong>Add Lyrics</strong> or <strong>Edit</strong> on an individual song.</p></div><div><h3>Sync each line to the song</h3><p>Choose <strong>Add Lyric Syncing</strong>. Play the song, then press <strong>Space</strong> or <strong>Stamp</strong> when the highlighted line begins. Move through the lyrics line by line.</p><p>Use Backspace to undo a stamp, P to pause, and the arrow keys to seek. Preview the result, adjust individual timestamps, and save the sync. For a recording with a different intro, adjust its lyric offset from <strong>Versions</strong>.</p></div></div><div class="shot-grid">{image('album-lyrics','The album lyric uploader, opened on an existing release.',assets)}{image('lyric-sync','The real lyric-sync editor, with line timing and preview controls.',assets)}</div></section>
<section id="playback"><p class="eyebrow">03 / Go anywhere</p><h2>Your music keeps going when the screen goes dark.</h2><p class="lede">Approved artist-uploaded audio is available to listeners by default for background playback and Apple CarPlay. Fans do not need to upload their own copy of your songs.</p><div class="cards"><div class="card"><h3>On the web</h3><p>Fans open your link and explore your music, lyrics, and playlists on a phone, tablet, or computer.</p></div><div class="card"><h3>In the background</h3><p>In the mobile app, eligible audio keeps playing when the app is in the background or the screen is locked.</p></div><div class="card"><h3>In Apple CarPlay</h3><p>Use the iPhone app in a CarPlay-compatible car. Approved artist audio can stream directly; saving a copy for offline playback is optional.</p></div></div><div class="note">CarPlay uses the iPhone app, rather than a browser tab. YouTube-only tracks do not become background or CarPlay audio automatically. Your approved uploaded recordings do.</div></section>
<section id="stats"><p class="eyebrow">04 / Understand the listening</p><h2>See what reaches people.</h2><p class="lede">Your artist dashboard brings together plays, listeners, returning listeners, listening time, hearts, playlist adds, and artist-page visits.</p><p>Choose your artist and date range to compare activity over time, then look at individual songs, listening locations, discovery sources, and the moments listeners loved. Open <strong>Artist Stats</strong> while signed in as the artist or a manager. Refresh to see the latest recorded listening activity.</p>{image('artist-stats','An actual Nouns Group artist dashboard, showing listening totals, daily plays, and song-level activity. Counts are a captured example, not live counters.',assets)}<div class="note">Listening time appears as timing events are recorded; older plays may not have duration data. Artist stats are available to authorized artists and managers. Listeners have their own account dashboard.</div><div class="buttons"><a class="button secondary" href="{link('/artist-stats')}">Open Artist Stats</a></div></section>
<section id="share"><p class="eyebrow">05 / Share the collection</p><h2>A link your audience can make their own.</h2><div class="split"><div><p>Share an artist, album, song, or playlist link. Listeners can explore the discography, read and heart lyrics, and add favorite tracks to their own playlists.</p><p>Start a listening room and share its invitation to listen together with friends and fans. Room guests can contribute to the queue according to the host’s settings.</p><p><a href="{link('/for-listeners')}">See the listener experience →</a></p></div><div>{image('discography','A real artist discography, with releases and catalog navigation.',assets)}</div></div></section><div class="closing"><h2>Bring your next release here.</h2><p class="muted">Upload the recordings. Add the words. Send your audience one link.</p><div class="buttons"><a class="button" href="{link('/artist-upload')}">Publish your music</a><a class="button secondary" href="{link('/')}">Start exploring now</a></div></div>
'''

def listeners(link, assets):
    return f'''
<div class="hero"><p class="eyebrow">For listeners</p><h1>Explore the records.<br>Build your collection.</h1><p class="lede">Go deep into artists’ discographies, make playlists, follow the lyrics, and listen together. Bring your listening history with you and see the story behind what you play.</p><div class="buttons"><a class="button" href="{link('/')}">Start exploring now</a><a class="button secondary" href="{link('/analytics')}">My listening stats</a></div></div><nav class="jump" aria-label="On this page"><a href="#playlists">Playlists &amp; artists</a><a href="#share">Share &amp; listen together</a><a href="#stats">Your stats</a><a href="#history">Spotify &amp; Google history</a><a href="#background">Upload background audio</a></nav>
<section id="playlists"><p class="eyebrow">01 / Make it yours</p><h2>One song can lead to a whole discography.</h2><div class="split"><div><h3>Build a playlist</h3><p>Sign in, explore artists or search for a song, and use <strong>Add to playlist</strong> from the song’s menu. Choose an existing playlist or create one, then keep adding tracks as you explore.</p><p>Open your playlist to arrange the songs and play it in order or shuffle. A collection can mix different artists and releases.</p><h3>Add an artist you cannot find</h3><p>Use <strong>Add Music</strong> or <strong>Import Music</strong> in Explore Artists to bring in an artist, release, or song using the available link and search import tools. Review the matches before adding them.</p><p>Catalog imports add artist and song information with playable source links. They do not upload a recording or claim an artist’s rights. If you are publishing your own music, use the <a href="{link('/for-artists')}">artist upload process</a>.</p></div><div>{image('discography','Explore an existing artist’s releases before adding songs to your playlists.',assets)}</div></div></section>
<section id="share"><p class="eyebrow">02 / Pass it on</p><h2>Share a favorite. Start a room.</h2><p class="lede">Use the share controls to send an artist, album, song, or playlist link. Your friends can open the same content and start listening.</p><p>Want a shared queue? Sign in, start a listening room, and invite friends with its link or QR code. The host controls playback and room settings; guests add their picks to the queue where allowed.</p>{image('share-hub','The application’s share hub, with content links and sharing tools.',assets + '/help')}</section>
<section id="stats"><p class="eyebrow">03 / Your listening, explained</p><h2>See the patterns in what you play.</h2><p class="lede">Everyone with an account can open their own listening dashboard. See artists, songs, albums, plays, listening time, and activity over time.</p><p>Open <strong>My Listening Data</strong> from your account menu, or go to <strong>My Data &amp; Analytics</strong>. Filter by platform, dates, artists, or songs, and switch between plays and hours where duration data is available. Refresh for the latest recorded activity.</p>{image('listener-analytics','A real account’s My Data & Analytics dashboard, including platform totals, listening charts, and activity patterns. This is a captured example; your dashboard shows your own history.',assets)}<div class="buttons"><a class="button secondary" href="{link('/analytics')}">Open My Data &amp; Analytics</a></div></section>
<section id="history"><p class="eyebrow">04 / Bring your history</p><h2>Your past listening is part of the collection.</h2><p class="lede">Upload Spotify and Google listening exports from the analytics page, review them, and bring those listening records into your personal stats.</p><details><summary>Import Spotify listening history</summary><div class="inside"><ol><li><strong>Request Spotify’s Extended Streaming History export.</strong><p>Download the export when Spotify makes it available, then unzip it.</p></li><li><strong>Open My Data &amp; Analytics → Import listening history.</strong><p>Choose <strong>Spotify</strong>, then select the streaming-history JSON files from the export. Include all the relevant JSON files for the period you want to bring in.</p></li><li><strong>Review and import.</strong><p>Check the preview before confirming. The import adds listening records to your private history. Reimported events are deduplicated, and IP addresses are stripped before storage.</p></li></ol>{image('spotify-history','The real Spotify history-import screen inside My Data & Analytics.',assets)}</div></details>
<details><summary>Import Google / YouTube Music listening history</summary><div class="inside"><ol><li><strong>Export your history with Google Takeout.</strong><p>Choose <strong>YouTube and YouTube Music</strong>, include history, and download and unzip the export. Find <code>watch-history.html</code> in its history folder.</p></li><li><strong>Open Import listening history → YouTube Takeout.</strong><p>Select the watch-history file. The importer identifies likely music locally and presents a preview; uncertain entries start unchecked so you can review them.</p></li><li><strong>Choose the music entries and confirm.</strong><p>Check the selection, then import it into your personal history. Takeout does not include listening duration, so these records contribute plays rather than invented playback hours.</p></li></ol>{image('google-history','The real YouTube Takeout import screen and its file instructions.',assets)}</div></details>
<div class="note"><strong>Listening history is a record of what you played.</strong> Importing it adds stats, rather than audio files or a playable collection. Use the next step to find music that is missing from the catalog.</div>
<details><summary>Add missing music from the analytics page</summary><div class="inside"><ol><li><strong>Find a missing artist or song in your imported history.</strong><p>Select <strong>Add to Jukebox</strong> beside a missing entry, without leaving analytics.</p></li><li><strong>Choose songs and find matches.</strong><p>Select the songs you want, then choose <strong>Find matches</strong> to search YouTube for playable sources.</p></li><li><strong>Check the matches before adding.</strong><p>Review the source videos and correct artist or song names where needed. Confirm the selected matches with <strong>Add songs</strong>. They become catalog entries you can explore and add to playlists.</p></li></ol>{image('history-to-catalog','The actual Add to Jukebox flow: choose songs, find them, check the matches, and add them.',assets)}<p class="muted">A source-video match is separate from a personal audio upload. It does not automatically enable background play or CarPlay.</p></div></details></section>
<section id="background"><p class="eyebrow">05 / Keep it playing</p><h2>Screen off. Music on.</h2><p class="lede">Approved artist-uploaded music is already available for background play and CarPlay. For other catalog songs, you can upload your own audio files for private playback.</p><details><summary>Upload your own background-play content</summary><div class="inside"><ol><li><strong>Sign in and open Settings → Audio Storage.</strong><p>You can also use <strong>Enable Background Play</strong> in playlist exploration or an artist/album’s audio controls.</p></li><li><strong>Select your audio files and review the matches.</strong><p>Match the files to the correct artist, album, and songs. Use the upload screen’s current storage allowance and check the track assignments before uploading.</p></li><li><strong>Play the uploaded audio in the mobile app.</strong><p>Your personal files stay private to your account. They can play with the screen locked or the app in the background, and stream in Apple CarPlay through the iPhone app. Save an offline copy on the phone if you want playback without a connection.</p></li></ol><p>Use the <strong>Background Enabled</strong> filter to find eligible content. A playlist is eligible as a whole only when every song has usable audio; a YouTube-only song in a mixed queue cannot keep playing in the background.</p></div></details><div class="cards"><div class="card"><h3>Artist audio</h3><p>Approved recordings uploaded by artists are available to listeners by default. You do not need a personal copy.</p></div><div class="card"><h3>Your uploads</h3><p>Audio you add through your personal storage is for your account, rather than public artist distribution.</p></div><div class="card"><h3>Apple CarPlay</h3><p>Connect the iPhone app to a compatible car. Eligible audio streams directly; downloading first is optional.</p></div></div></section><div class="closing"><h2>Find your next favorite.</h2><p class="muted">Explore an artist. Make a playlist. Bring a friend.</p><div class="buttons"><a class="button" href="{link('/')}">Start exploring now</a><a class="button secondary" href="{link('/analytics')}">Explore your listening history</a></div></div>
'''

BRANDS = [
    dict(id='sj',name='Suffering Jukebox',url='https://sufferingjukebox.stream',logo='/suffering-jukebox-text-logo.png',bg='#120d17',card='#1c1624',ink='#faf5ed',muted='#bdb1c5',accent='#ff8c57',line='#3c3047'),
    dict(id='lp',name='Listening Party',url='https://listeningparty.stream',logo='/brand/lp/listening-party-text-logo.png',bg='#140817',card='#211027',ink='#fdf3df',muted='#c4b2c9',accent='#ff8c57',line='#43254e'),
    dict(id='rk',name='Record Keeper',url='https://www.outlawapps.online/record-keeper',logo='/record-keeper/wordmark-dark.png',bg='#171717',card='#222222',ink='#fff8ed',muted='#bfb8b0',accent='#ef8b63',line='#414141'),
]

def render(b, audience):
    rk = b['id'] == 'rk'
    base = '/record-keeper' if rk else ''
    assets = base + '/images/guides'
    def link(path):
        if rk:
            return base + ('' if path == '/' else path) if path in ['/', '/for-artists', '/for-listeners'] else 'https://listeningparty.stream' + path
        return path
    title = 'For Artists' if audience == 'artists' else 'For Listeners'
    desc = ('Upload your music, add and sync lyrics, share your discography, and understand your audience with artist stats.' if audience == 'artists' else 'Build playlists, explore artists, share music, upload background audio, and bring Spotify and Google listening history into your stats.')
    body = artists(link, assets) if audience == 'artists' else listeners(link, assets)
    body = body.replace('Request Spotify’s Extended Streaming History export.', '<a href="https://support.spotify.com/us/article/understanding-your-data/" target="_blank" rel="noopener">Request Spotify’s Extended Streaming History export.</a>')
    body = body.replace('Export your history with Google Takeout.', '<a href="https://takeout.google.com/" target="_blank" rel="noopener">Export your history with Google Takeout.</a>')
    # The sharing screenshot predates this guide and comes from the actual help captures.
    body = body.replace(assets + '/help/share-hub.png', base + '/images/help/share-hub.png')
    preview = '<div class="preview">Record Keeper brand preview · Sign-in, uploads, and account tools open on Listening Party. <a href="https://www.outlawapps.online/">Back to the garage</a></div>' if rk else ''
    colors = ';'.join('--'+k+':'+b[k] for k in ['bg','card','ink','muted','accent','line'])
    icon = '/record-keeper/icon.png' if rk else '/brand/lp/favicon.png' if b['id']=='lp' else '/favicon.png'
    nav = ''.join(f'<a href="{link("/for-"+a)}"'+(' aria-current="page"' if a == audience else '')+f'>For {a.title()}</a>' for a in ['artists','listeners'])
    html = f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title} | {b['name']}</title><meta name="description" content="{desc}"><meta name="robots" content="{'noindex, nofollow' if rk else 'index, follow'}"><link rel="canonical" href="{b['url']}/for-{audience}"><meta property="og:type" content="website"><meta property="og:title" content="{title} | {b['name']}"><meta property="og:description" content="{desc}"><meta property="og:url" content="{b['url']}/for-{audience}"><meta property="og:image" content="{b['url'].replace('/record-keeper','')+b['logo']}"><link rel="icon" href="{icon}"><style>:root{{{colors}}}{CSS}</style></head><body>{preview}<header><div class="top"><a class="brand" href="{link('/')}"><img src="{b['logo']}" alt="{b['name']}"></a><nav aria-label="Main navigation"><a href="{link('/')}">Explore</a>{nav}<a href="{link('/help')}">Help</a></nav></div></header><main>{body}</main><footer><div class="footer-in"><span>{b['name']} · Explore. Create. Listen together.</span><span>Real product screens · Captured October 5, 2026 · Account dashboards require sign-in.</span></div></footer></body></html>'''
    if not rk:
        html = html.replace(b['url'] + b['logo'], b['url'] + ('/brand/lp/og-image.png' if b['id']=='lp' else '/og-image.png'))
    return html

for brand in BRANDS:
    if brand['id'] == 'rk' and len(sys.argv) < 2:
        continue
    for audience in ['artists', 'listeners']:
        if brand['id']=='rk':
            dest = Path(sys.argv[1]) / 'public/record-keeper' / ('for-' + audience)
        else:
            dest = ROOT / 'public' / ('for-' + audience)
            if brand['id']=='lp': dest /= 'lp'
        dest.mkdir(parents=True,exist_ok=True)
        (dest/'index.html').write_text(render(brand,audience),encoding='utf-8')
        print('Built '+brand['name']+' /for-'+audience)
if len(sys.argv)>1:
    for folder in ['guides','help']:
        src = ROOT/'public/images'/folder
        dest = Path(sys.argv[1])/'public/record-keeper/images'/folder
        dest.mkdir(parents=True,exist_ok=True)
        files = list(src.glob('*')) if folder=='guides' else [src/'share-hub.png']
        for file in files:
            if file.is_file(): shutil.copy2(file,dest/file.name)
